#include <stdio.h>

static int neg_int(int x) { return -x; }

static double neg_double(double x) { return -x; }

int main(void) {
  printf("%d\n", neg_int(7));
  printf("%d\n", neg_int(-12));
  printf("%f\n", neg_double(1.5));
  return 0;
}

